import sys


def main():
    text = sys.stdin.read()
    config, _, queries = text.partition("===\n")
    data = {}
    current_section = ""
    for line in config.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("["):
            current_section = line[1:-1].strip().lower()
            if current_section not in data:
                data[current_section] = {}
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip().lower()
        value = value.strip()
        # Handle quoted values
        if value.startswith('"'):
            end_quote = value.find('"', 1)
            if end_quote != -1:
                value = value[1 : end_quote].rstrip()
        else:
            # Remove comments after ';' or '#' that are preceded by space or tab
            comment_index = None
            for i in range(len(value)):
                if (i == 0 and value[i] in (';', '#')):
                    continue
                elif (i > 0 and value[i] in (';', '#') and value[i - 1] in (' ', '\t')):
                    comment_index = i
                    break
            if comment_index is not None:
                value = value[:comment_index].rstrip()
        data.setdefault(current_section, {})[key] = value

    for query_line in queries.splitlines():
        query_line = query_line.strip()
        if not query_line:
            continue
        parts = query_line.split('.', 1)
        section_name = parts[0].strip().lower() if len(parts) > 0 else ""
        key_name = parts[1].strip().lower() if len(parts) > 1 else ""
        value = data.get(section_name, {}).get(key_name, "NOT FOUND")
        print(value)


if __name__ == "__main__":
    main()
